import { Component, OnInit, inject, ChangeDetectorRef } from '@angular/core';
import { CommonModule, NgIf, NgFor } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { environment } from '../../../../environments/environment';
import { QuizService } from '../../../core/services/quiz.service';

@Component({
  selector: 'app-ats-pipeline',
  standalone: true,
  imports: [CommonModule, NgIf, NgFor],
  templateUrl: './ats-pipeline.component.html',
  styleUrls: ['./ats-pipeline.component.css'],
})
export class AtsPipelineComponent implements OnInit {
  private cdr = inject(ChangeDetectorRef);
  private http = inject(HttpClient);
  private quizService = inject(QuizService);

  applicationsList: any[] = [];
  selectedApplication: any = null;

  quizAnswersData: {
    has_quiz: boolean;
    quiz_title: string | null;
    answers: any[];
  } | null = null;
  isLoadingQuizAnswers = false;

  selectedJobTitle: string = 'all';

  ngOnInit() {
    this.fetchApplications();
  }

  fetchApplications() {
    this.http
      .get<{ applications: any[] }>(`${environment.apiUrl}/recruiter/ats/applications`)
      .subscribe({
        next: (data) => {
          this.applicationsList =
            data && Array.isArray(data.applications) ? data.applications : [];
          this.cdr.detectChanges();
        },
        error: (err) => console.error('Erreur ATS :', err),
      });
  }

  getFilteredCandidatesCount(jobTitle: string): number {
    return this.applicationsList.filter((app) => {
      if (jobTitle !== 'all' && app.job_title !== jobTitle) return false;
      if (!app.status) return true;
      const currentStatus = app.status.toLowerCase().trim();
      return (
        currentStatus.includes('nouv') ||
        currentStatus.includes('att') ||
        currentStatus === 'pending' ||
        currentStatus.includes('entre') ||
        currentStatus.includes('tech') ||
        currentStatus.includes('prop') ||
        currentStatus.includes('offr')
      );
    }).length;
  }

  getUniqueJobTitles(): string[] {
    if (!this.applicationsList) return [];

    const visibleApps = this.applicationsList.filter((app) => {
      if (!app.status) return true;
      const currentStatus = app.status.toLowerCase().trim();
      return (
        currentStatus.includes('nouv') ||
        currentStatus.includes('att') ||
        currentStatus === 'pending' ||
        currentStatus.includes('entre') ||
        currentStatus.includes('tech') ||
        currentStatus.includes('prop') ||
        currentStatus.includes('offr')
      );
    });

    const titles = visibleApps.map((app) => app.job_title).filter((title) => !!title);
    return [...new Set(titles)];
  }

  onJobFilterChange(event: any) {
    this.selectedJobTitle = event.target.value;
    this.cdr.detectChanges();
  }

  changeCandidateStatus(applicationId: number, newStatus: string) {
    this.http
      .post(`${environment.apiUrl}/recruiter/ats/update-status`, {
        id: applicationId,
        status: newStatus,
      })
      .subscribe({
        next: () => {
          const appIndex = this.applicationsList.findIndex((a) => a.id === applicationId);
          if (appIndex !== -1) {
            this.applicationsList[appIndex].status = newStatus;
          }
          this.onCloseDetails();
        },
        error: () => alert('Impossible de modifier le statut.'),
      });
  }

  getCandidatesByStatus(statusName: string): any[] {
    return this.applicationsList.filter((app) => {
      if (this.selectedJobTitle !== 'all' && app.job_title !== this.selectedJobTitle) {
        return false;
      }

      if (!app.status) return statusName === 'Nouveau';

      const currentStatus = app.status.toLowerCase().trim();
      if (statusName === 'Nouveau')
        return (
          currentStatus.includes('nouv') ||
          currentStatus.includes('att') ||
          currentStatus === 'pending'
        );
      if (statusName === 'Entretien')
        return currentStatus.includes('entre') || currentStatus.includes('tech');
      if (statusName === 'Proposition')
        return currentStatus.includes('prop') || currentStatus.includes('offr');

      return false;
    });
  }

  onSelectApplication(app: any) {
    this.selectedApplication = { ...app };
    this.quizAnswersData = null;
    this.isLoadingQuizAnswers = true;
    this.cdr.detectChanges();

    this.quizService.getApplicationQuizAnswers(app.id).subscribe({
      next: (data) => {
        this.quizAnswersData = data;
        this.isLoadingQuizAnswers = false;
        this.cdr.detectChanges();
      },
      error: () => {
        this.quizAnswersData = { has_quiz: false, quiz_title: null, answers: [] };
        this.isLoadingQuizAnswers = false;
        this.cdr.detectChanges();
      },
    });
  }

  onCloseDetails() {
    this.selectedApplication = null;
    this.quizAnswersData = null;
    this.isLoadingQuizAnswers = false;
    this.cdr.detectChanges();
  }

  openCandidateCV(candidateId: number) {
    if (!candidateId) return;
    window.open(`/candidate/cv-view/${candidateId}`, '_blank');
  }

  logoUrl(filename: string | null): string {
    return filename ? `${environment.assetsUrl}/logos/${filename}` : 'assets/images/default-avatar.png';
  }
}
<div class="ats-container">
  <div class="ats-card">
    <div class="card-header">
      <h3><i class="bi bi-people-fill"></i> Suivi des Candidats (Pipeline ATS)</h3>
      <p>Suivez pas à pas la progression de vos candidats dans le tunnel de recrutement.</p>
    </div>
<!-- 🔍 FILTRE PAR OFFRE D'EMPLOI -->
<div class="job-filter-container" style="margin-bottom: 20px; display: flex; align-items: center; gap: 12px;">
  <label style="font-size: 13px; font-weight: 700; color: #475569; text-transform: uppercase;">Filtrer par offre :</label>
  
  
  <select (change)="onJobFilterChange($event)" style="padding: 10px 14px; border: 1px solid #cbd5e1; border-radius: 6px; font-size: 14px; color: #1e293b; background: #fff; width: 300px;">
  
  <!-- 🟢 Compteur global parfaitement synchronisé (Affiche 14) -->
  <option value="all">Tous les candidats ({{ getFilteredCandidatesCount('all') }})</option>
  
  <!-- 🟢 Compteurs par offre mis à jour en temps réel -->
  <option *ngFor="let title of getUniqueJobTitles()" [value]="title">
    {{ title }} ({{ getFilteredCandidatesCount(title) }})
  </option>

</select>

</div>

    <!-- Les colonnes Kanban du logiciel de recrutement -->
    <div class="pipeline-grid">
      
      <!-- 1. Colonne : Nouveaux CV -->
      <div class="pipeline-column">
        <div class="column-header">
          Nouveaux CV 
          <span class="count">{{ getCandidatesByStatus('Nouveau').length }}</span>
        </div>
        
        <div *ngFor="let app of getCandidatesByStatus('Nouveau')" 
             (click)="onSelectApplication(app)"
             class="candidate-item">
          <h5>{{ app.name }}</h5>
          <p>{{ app.job_title }}</p>
          <span class="location"><i class="bi bi-geo-alt"></i> {{ app.address || 'Tunis' }}</span>
        </div>

        <!-- Espace visuel si la colonne est vide -->
        <div *ngIf="getCandidatesByStatus('Nouveau').length === 0" class="empty-placeholder">
          <svg xmlns="http://w3.org" width="24" height="24" fill="currentColor" viewBox="0 0 16 16"><path d="M4.5 1a1 1 0 0 0-1 1v12a1 1 0 0 0 1 1h7a1 1 0 0 0 1-1V2a1 1 0 0 0-1-1zM3 2a2 2 0 0 1 2-2h7a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2zm4.5 5.5a.5.5 0 0 1 .5-.5h3a.5.5 0 0 1 0 1H8a.5.5 0 0 1-.5-.5M8 9a.5.5 0 0 1 .5-.5h3a.5.5 0 0 1 0 1H8A.5.5 0 0 1 8 9m.5 2.5a.5.5 0 0 1 0-1h2a.5.5 0 0 1 0 1z"/></svg>
          <p>Aucun nouveau CV</p>
        </div>
      </div>

      <!-- 2. Colonne : Entretien Tech -->
      <div class="pipeline-column">
        <div class="column-header">
          Entretien Tech 
          <span class="count">{{ getCandidatesByStatus('Entretien').length }}</span>
        </div>
        
        <div *ngFor="let app of getCandidatesByStatus('Entretien')" 
             (click)="onSelectApplication(app)"
             class="candidate-item border-orange">
          <h5>{{ app.name }}</h5>
          <p>{{ app.job_title }}</p>
          <span class="location"><i class="bi bi-geo-alt"></i> {{ app.address || 'Tunis' }}</span>
        </div>

        <!-- Espace visuel si la colonne est vide -->
        <div *ngIf="getCandidatesByStatus('Entretien').length === 0" class="empty-placeholder">
          <svg xmlns="http://w3.org" width="24" height="24" fill="currentColor" viewBox="0 0 16 16"><path d="M10.854 7.146a.5.5 0 0 1 0 .708l-3 3a.5.5 0 0 1-.708 0l-1.5-1.5a.5.5 0 1 1 .708-.708L7.5 9.793l2.646-2.647a.5.5 0 0 1 .708 0"/><path d="M3.5 0a.5.5 0 0 1 .5.5V1h8V.5a.5.5 0 0 1 1 0V1h1a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H2a2 2 0 0 1-2-2V3a2 2 0 0 1 2-2h1V.5a.5.5 0 0 1 .5-.5M1 4v10a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1V4z"/></svg>
          <p>Aucun entretien planifié</p>
        </div>
      </div>

      <!-- 3. Colonne : Proposition -->
      <div class="pipeline-column">
        <div class="column-header">
          Proposition 
          <span class="count">{{ getCandidatesByStatus('Proposition').length }}</span>
        </div>
        
        <div *ngFor="let app of getCandidatesByStatus('Proposition')" 
             (click)="onSelectApplication(app)"
             class="candidate-item border-green">
          <h5>{{ app.name }}</h5>
          <p>{{ app.job_title }}</p>
          <span class="location"><i class="bi bi-geo-alt"></i> {{ app.address || 'Tunis' }}</span>
        </div>

        <!-- Espace visuel si la colonne est vide -->
        <div *ngIf="getCandidatesByStatus('Proposition').length === 0" class="empty-placeholder">
          <svg xmlns="http://w3.org" width="24" height="24" fill="currentColor" viewBox="0 0 16 16"><path d="M16 8A8 8 0 1 1 0 8a8 8 0 0 1 16 0m-3.97-3.03a.75.75 0 0 0-1.08.022L7.477 9.417 5.384 7.323a.75.75 0 0 0-1.06 1.06L6.97 11.03a.75.75 0 0 0 1.079-.02l3.992-4.99a.75.75 0 0 0-.01-1.05z"/></svg>
          <p>Aucune proposition émise</p>
        </div>
      </div>

    </div>
  </div>
</div>

<!-- ========================================================================== -->
<!-- 🚀 FENÊTRE MODALE DE CONSULTATION DE LA CANDIDATURE                        -->
<!-- ========================================================================== -->
<div *ngIf="selectedApplication" class="modal-overlay" (click)="onCloseDetails()">
<div class="modal-content" (click)="$event.stopPropagation()" style="width: 640px; max-width: 95%; max-height: 90vh; display: flex; flex-direction: column; gap: 16px;">
    
    <!-- En-tête -->
    <div class="modal-header">
      <h3>Candidature de {{ selectedApplication.name }}</h3>
      <button class="close-btn" (click)="onCloseDetails()">&times;</button>
    </div>


        <!-- Corps des détails avec intégration de l'avatar -->
    <div class="modal-body">
      
      <details class="ats-section-card" open>
        <summary class="ats-section-summary">
          <span><i class="bi bi-person-vcard-fill"></i> Profil candidat</span>
          <i class="bi bi-chevron-down"></i>
        </summary>

        <div class="ats-section-content">
          <div style="display: flex; gap: 24px; align-items: flex-start; margin-bottom: 20px;">
            <div style="flex-shrink: 0; display: flex; flex-direction: column; align-items: center; gap: 10px; width: 110px;">
              <div style="width: 85px; height: 85px; border-radius: 50%; border: 1px solid #cbd5e1; overflow: hidden; background: #ffffff; display: flex; align-items: center; justify-content: center;">
                <img [src]="logoUrl(selectedApplication.avatar_logo)"
                  (error)="$any($event.target).src='assets/images/default-avatar.png'"
                  alt="Photo du candidat"
                  style="width: 100%; height: 100%; object-fit: cover;">
              </div>

              <button (click)="openCandidateCV(selectedApplication.candidate_id)"
                [disabled]="!selectedApplication.cv_summary || selectedApplication.cv_summary.trim() === ''"
                [style.opacity]="selectedApplication.cv_summary && selectedApplication.cv_summary.trim() !== '' ? '1' : '0.5'"
                [style.cursor]="selectedApplication.cv_summary && selectedApplication.cv_summary.trim() !== '' ? 'pointer' : 'not-allowed'"
                [style.pointer-events]="selectedApplication.cv_summary && selectedApplication.cv_summary.trim() !== '' ? 'auto' : 'none'"
                style="background: #ffffff; border: 1px solid #cbd5e1; color: #0284c7; padding: 6px 4px; border-radius: 4px; font-size: 11px; font-weight: 700; width: 100%; text-align: center; display: inline-flex; align-items: center; justify-content: center; gap: 4px; box-shadow: 0 1px 2px rgba(0,0,0,0.05);">
                <svg xmlns="http://w3.org" width="11" height="11" fill="currentColor" viewBox="0 0 16 16">
                  <path d="M14 14V4.5L9.5 0H4a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h8a2 2 0 0 0 2-2M9.5 1A1.5 1.5 0 0 1 11 2.5V4h3v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1z"/>
                </svg>
                {{ selectedApplication.cv_summary && selectedApplication.cv_summary.trim() !== '' ? 'Consulter le CV' : 'Aucun CV' }}
              </button>
            </div>

            <div style="flex-grow: 1; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px;">
              <div style="display: flex; flex-direction: column; gap: 10px;">
                <div class="info-row" style="display: flex;">
                  <span class="info-label" style="width: 140px; flex-shrink: 0;">Ville / Région :</span>
                  <span class="info-value">{{ selectedApplication.address || 'Non spécifiée' }}</span>
                </div>

                <div class="info-row" style="display: flex;">
                  <span class="info-label" style="width: 140px; flex-shrink: 0;">Situation actuelle :</span>
                  <span class="info-value">{{ selectedApplication.job_status || 'Non renseignée' }}</span>
                </div>

                <div class="info-row" style="display: flex;">
                  <span class="info-label" style="width: 140px; flex-shrink: 0;">Disponibilité :</span>
                  <span class="info-value">{{ selectedApplication.availability || 'Non renseignée' }}</span>
                </div>
              </div>

              <div style="display: flex; flex-direction: column; gap: 10px;">
                <div class="info-row" style="display: flex;">
                  <span class="info-label" style="width: 140px; flex-shrink: 0;">Contrat souhaité :</span>
                  <span class="info-value">{{ selectedApplication.job_type || 'Non renseigné' }}</span>
                </div>

                <div class="info-row" style="display: flex;">
                  <span class="info-label" style="width: 140px; flex-shrink: 0;">Date de naissance :</span>
                  <span class="info-value">{{ selectedApplication.birth_date ? (selectedApplication.birth_date | date:'dd/MM/yyyy') : 'Non renseignée' }}</span>
                </div>

                <div class="info-row" style="display: flex; align-items: center;">
                  <span class="info-label" style="width: 140px; flex-shrink: 0;">Réseaux :</span>
                  <div style="display: flex; gap: 10px; flex-wrap: wrap;">
                    <a *ngIf="selectedApplication.linkedin && selectedApplication.linkedin.trim() !== ''"
                      [href]="selectedApplication.linkedin"
                      target="_blank"
                      class="social-badge-btn linkedin-badge">
                      <i class="bi bi-linkedin"></i> LinkedIn
                    </a>

                    <a *ngIf="selectedApplication.github && selectedApplication.github.trim() !== ''"
                      [href]="selectedApplication.github"
                      target="_blank"
                      class="social-badge-btn github-badge">
                      <i class="bi bi-github"></i> GitHub
                    </a>

                    <span *ngIf="(!selectedApplication.linkedin || selectedApplication.linkedin.trim() === '') && (!selectedApplication.github || selectedApplication.github.trim() === '')"
                      style="color: #94a3b8; font-style: italic; font-size: 13px; font-weight: 500;">
                      Non renseigné
                    </span>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <div class="summary-box" style="margin-top: 15px; padding: 16px; background: #f8fafc; border-radius: 8px; border-left: 4px solid #0ea5e9;">
            <span class="summary-title" style="color: #0f172a; font-weight: 700; font-size: 13px; display: block; margin-bottom: 8px;">
              Résumé du profil & Compétences clés
            </span>
            <p class="summary-text" style="margin: 0; color: #475569; font-size: 13px; line-height: 1.6; white-space: pre-line;">
              {{ selectedApplication.cv_summary || selectedApplication.cv_Summary || selectedApplication.summary || "Le candidat n'a pas encore rédigé de présentation de profil sur son espace TunJob." }}
            </p>
          </div>
        </div>
      </details>

      <details class="ats-section-card">
        <summary class="ats-section-summary">
          <span><i class="bi bi-patch-question-fill"></i> Réponses quiz</span>
          <i class="bi bi-chevron-down"></i>
        </summary>

        <div class="ats-section-content">
          @if (isLoadingQuizAnswers) {
            <div class="quiz-answers-section" style="margin-top: 6px;">
              <p style="color: #64748b; font-size: 13px; margin: 0;"><i class="bi bi-arrow-clockwise"></i> Chargement des réponses au quiz…</p>
            </div>
          } @else if (quizAnswersData) {
            @if (quizAnswersData.has_quiz && quizAnswersData.answers.length) {
              <div class="quiz-answers-section">
                <div class="quiz-answers-header">
                  <h4><i class="bi bi-patch-question-fill"></i> Réponses au questionnaire</h4>
                  <span class="quiz-answers-subtitle">{{ quizAnswersData.quiz_title }}</span>
                </div>
                <div class="quiz-answers-list">
                  @for (answer of quizAnswersData.answers; track answer.question_id; let i = $index) {
                    <div class="quiz-answer-item" [class.correct]="answer.is_correct" [class.incorrect]="!answer.is_correct">
                      <div class="quiz-answer-q">
                        <span class="quiz-answer-num">Q{{ i + 1 }}</span>
                        {{ answer.question_text }}
                      </div>
                      <div class="quiz-answer-a">
                        @if (answer.is_correct) {
                          <i class="bi bi-check2-circle"></i>
                        } @else {
                          <i class="bi bi-x-circle"></i>
                        }
                        {{ answer.selected_choice_text }}
                      </div>
                    </div>
                  }
                </div>
              </div>
            } @else if (quizAnswersData.has_quiz) {
              <div class="quiz-answers-section quiz-answers-empty">
                <p>Aucune réponse enregistrée pour ce quiz.</p>
              </div>
            } @else {
              <div class="quiz-answers-section quiz-answers-empty">
                <p>Cette offre ne contient pas de quiz.</p>
              </div>
            }
          }
        </div>
      </details>
    </div>


<!-- Pied de page avec boutons de décision ATS Pro corrigé par le CSS -->
<!-- Pied de page unifié géré par le CSS corrigé -->
<!-- ================= PIED DE PAGE ATS UNIFIÉ ET CENTRÉ ================= -->
<div class="modal-footer">
  
  <!-- 1. Bouton Accepter (Vert) -->
  <button type="button" 
          (click)="changeCandidateStatus(selectedApplication.id, 'Proposition')" 
          style="background: #10b981; color: white; border: none; padding: 8px 14px; border-radius: 6px; font-size: 12px; font-weight: 600; cursor: pointer; display: inline-flex; align-items: center; gap: 6px; transition: background 0.2s;">
    <svg xmlns="http://w3.org" width="12" height="12" fill="currentColor" viewBox="0 0 16 16"><path d="M16 8A8 8 0 1 1 0 8a8 8 0 0 1 16 0m-3.97-3.03a.75.75 0 0 0-1.08.022L7.477 9.417 5.384 7.323a.75.75 0 0 0-1.06 1.06L6.97 11.03a.75.75 0 0 0 1.079-.02l3.992-4.99a.75.75 0 0 0-.01-1.05z"/></svg>
    Accepter
  </button>

  <!-- 2. Bouton En attente (Gris Ardoise) -->
  <button type="button" 
          (click)="changeCandidateStatus(selectedApplication.id, 'Nouveau')" 
          style="background: #64748b; color: white; border: none; padding: 8px 14px; border-radius: 6px; font-size: 12px; font-weight: 600; cursor: pointer; display: inline-flex; align-items: center; gap: 6px; transition: background 0.2s;">
    <svg xmlns="http://w3.org" width="12" height="12" fill="currentColor" viewBox="0 0 16 16"><path d="M8 15A7 7 0 1 1 8 1a7 7 0 0 0 0 14m0 1A8 8 0 1 0 8 0a8 8 0 0 0 0 16"/><path d="M5 6.25a1.25 1.25 0 1 1 2.5 0v3.5a1.25 1.25 0 1 1-2.5 0zm4 0a1.25 1.25 0 1 1 2.5 0v3.5a1.25 1.25 0 1 1-2.5 0z"/></svg>
    En attente
  </button>
  
  <!-- 3. Bouton Entretien Technique (Orange) -->
  <button type="button" 
          (click)="changeCandidateStatus(selectedApplication.id, 'Entretien')" 
          style="background: #f97316; color: white; border: none; padding: 8px 14px; border-radius: 6px; font-size: 12px; font-weight: 600; cursor: pointer; display: inline-flex; align-items: center; gap: 6px; transition: background 0.2s;">
    <svg xmlns="http://w3.org" width="12" height="12" fill="currentColor" viewBox="0 0 16 16"><path d="M8 16A8 8 0 1 0 8 0a8 8 0 0 0 0 16m7-8A7 7 0 1 1 1 8a7 7 0 0 1 14 0m-8.5-4.5A.5.5 0 0 1 7 4v3.5h2.5a.5.5 0 0 1 0 1H6.5a.5.5 0 0 1-.5-.5V4a.5.5 0 0 1 .5-.5"/></svg>
    Entretien
  </button>

  <!-- 4. Bouton Rejeter (Rouge) -->
  <button type="button" 
          (click)="changeCandidateStatus(selectedApplication.id, 'Rejete')" 
          style="background: #ef4444; color: white; border: none; padding: 8px 14px; border-radius: 6px; font-size: 12px; font-weight: 600; cursor: pointer; display: inline-flex; align-items: center; gap: 6px; transition: background 0.2s;">
    <svg xmlns="http://w3.org" width="12" height="12" fill="currentColor" viewBox="0 0 16 16"><path d="M16 8A8 8 0 1 1 0 8a8 8 0 0 1 16 0M5.354 4.646a.5.5 0 1 0-.708.708L7.293 8l-2.647 2.646a.5.5 0 0 0 .708.708L8 8.707l2.646 2.647a.5.5 0 0 0 .708-.708L8.707 8l2.647-2.646a.5.5 0 0 0-.708-.708L8 7.293z"/></svg>
    Rejeter
  </button>

  <!-- 5. Bouton Fermer -->
  <button type="button" 
          class="btn-secondary" 
          (click)="onCloseDetails()" 
          style="padding: 8px 18px; font-size: 12px; font-weight: 600; border-radius: 6px; cursor: pointer; margin: 0;">
    Fermer
  </button>

</div>
  </div>
</div>
